/* Carmen WMS · stock e inventario (saldos, kardex, conteos, ajustes, ABC, mín/máx) y mapa de almacén. */
"use strict";

/* ===================================================================== STOCK */
function outs90(code) { const lim = daysAgoISO(90); return sum(KARDEX.filter(k => k.codigo === code && k.dir === "out" && ["Picking", "Despacho"].includes(k.tipo) && k.ts >= lim), k => Math.abs(k.qty)); }
function daysOfStock(code) { const o = outs90(code); const s = stockOf(code); return o ? Math.round(s / (o / 90)) : null; }
function iraOf(c) { const ls = (c.lines || []).filter(l => l.counted); return ls.length ? ls.filter(l => !lineDiff(l).length).length / ls.length : c.ira || 0; }
function lineDiff(l) {
  if (!l.counted) return [];
  const keys = uniq([...(l.items || []).map(i => `${i.codigo}|${i.lote}`), ...(l.conteo || []).map(i => `${i.codigo}|${i.lote}`)]);
  return keys.map(k => { const [codigo, lote] = k.split("|"); const sys = sum((l.items || []).filter(i => i.codigo === codigo && String(i.lote) === lote), i => i.sys); const cnt = sum((l.conteo || []).filter(i => i.codigo === codigo && String(i.lote) === lote), i => i.qty); return { codigo, lote, sys, cnt, dif: cnt - sys }; }).filter(d => d.dif !== 0);
}
VIEWS.stock = () => {
  const sub = state.sub.stock || "saldos";
  const tabs = [["saldos", "Stock por ubicación"], ["kardex", "Kardex"], ["conteos", "Inventario cíclico"], ["ajustes", `Ajustes${whAdj().filter(a => a.estado === "Pendiente").length ? ` (${whAdj().filter(a => a.estado === "Pendiente").length})` : ""}`], ["abc", "Rotación ABC"], ["minmax", "Máximos y mínimos"]];
  let body = "";
  if (sub === "saldos") {
    const q = fq("stockQ"), est = fv("stockEst");
    const rows = whStock().filter(s => (!q || has(s.codigo, q) || has(s.loc, q) || has(P(s.codigo).desc, q) || has(s.lote, q)) && (est === "Todos" || (est === "Disponible" && s.estado === "DISPONIBLE" && !(s.reservado > 0)) || (est === "Reservado" && s.reservado > 0) || (est === "Cuarentena" && ["CUARENTENA", "BLOQUEADO"].includes(s.estado)) || (est === "Vencido" && isExpired(s)) || (est === "Muelle" && zoneOf(s.loc) === "Recepción"))).sort((a, b) => ((L(a.loc) || {}).sort || 0) - ((L(b.loc) || {}).sort || 0) || a.codigo.localeCompare(b.codigo));
    body = `<div class="toolbar">${searchBox("stockQ", "SKU, descripción, ubicación o lote")}${chipBar("stockEst", ["Todos", "Disponible", "Reservado", "Cuarentena", "Vencido", ["Muelle", "En muelle"]])}<div style="flex:1"></div><span class="muted small">${fmt(rows.length)} saldos · ${fmt(uniq(rows.map(r => r.codigo)).length)} SKU · <b class="num">${fmt(sum(rows, r => r.qty))}</b> un.</span><button class="btn sm" data-a="stock-export">${ic("download")} Exportar</button></div>
      ${table([{ h: "Ubicación", f: s => `<span class="mono link" data-loc="${esc(s.loc)}">${esc(s.loc)}</span>` }, { h: "SKU", f: s => `<span class="mono link" data-prod="${esc(s.codigo)}">${esc(s.codigo)}</span><div class="small muted">${esc(P(s.codigo).desc)}</div>` }, { h: "UM", f: s => esc(P(s.codigo).um) }, { h: "Lote", f: s => `<span class="mono small">${esc(s.lote || "—")}</span>` }, { h: "Ingreso", f: s => fmtD(s.ingreso) }, { h: "Vence", f: s => s.venc ? `<span style="color:${isExpired(s) ? "var(--bad)" : "inherit"}">${fmtD(s.venc)}</span>` : `<span class="muted">—</span>` }, { h: "Cantidad", a: "r", f: s => `<b class="num">${fmt(s.qty)}</b>` }, { h: "Reservado", a: "r", f: s => s.reservado ? `<span class="num" style="color:var(--warn)">${fmt(s.reservado)}</span>` : `<span class="muted">0</span>` }, { h: "Estado", f: s => pillFor(s.estado) }, { h: "", f: s => can("reubicar") ? `<button class="btn sm ghost icon" data-a="mv-open" data-loc="${esc(s.loc)}" data-cod="${esc(s.codigo)}" data-lote="${esc(s.lote || "")}" title="Reubicar">${ic("move")}</button>` : "" }], rows, { id: "stock", empty: "Sin saldos con esos filtros" })}`;
  } else if (sub === "kardex") {
    const q = fq("kdxQ"), by = fv("kdxBy", "producto"), d1 = state.filters.kdx1 || daysAgoISO(30), d2 = state.filters.kdx2 || todayISO(), tipo = fv("kdxTipo");
    const match = k => !q || (by === "producto" ? has(k.codigo, q) || has(P(k.codigo).desc, q) || has(k.lote, q) : by === "documento" ? has(k.doc, q) : by === "usuario" ? has(k.user, q) || has(userName(k.user), q) : has(k.from, q) || has(k.to, q));
    const rows = whKdx().filter(k => k.ts.slice(0, 10) >= d1 && k.ts.slice(0, 10) <= d2 && (tipo === "Todos" || k.tipo === tipo) && match(k));
    body = `<div class="toolbar">${searchBox("kdxQ", by === "producto" ? "SKU, descripción o lote" : by === "documento" ? "Nro de documento (ING, PED, AJ…)" : by === "usuario" ? "Usuario" : "Ubicación")}<div class="seg">${[["producto", "Por producto"], ["documento", "Por documento"], ["usuario", "Por usuario"], ["ubicacion", "Por ubicación"]].map(([k, l]) => `<button class="${by === k ? "on" : ""}" data-f="kdxBy" data-v="${k}">${l}</button>`).join("")}</div><select class="select" style="width:auto;min-height:36px" data-fsel="kdxTipo">${opts(["Todos", ...uniq(whKdx().map(k => k.tipo))], tipo)}</select><div style="flex:1"></div><input class="input" type="date" data-fdate="kdx1" value="${d1}" style="width:150px;min-height:36px"><input class="input" type="date" data-fdate="kdx2" value="${d2}" style="width:150px;min-height:36px"><button class="btn sm" data-a="kdx-export">${ic("download")} Exportar</button></div>
      ${table([{ h: "Fecha / hora", f: k => `<span class="num small">${esc(k.ts)}</span>` }, { h: "Movimiento", f: k => `<span class="pill ${k.dir === "in" ? "ok" : k.dir === "out" ? "bad" : "info"} plain">${esc(k.tipo)}</span>` }, { h: "SKU", f: k => `<span class="mono link" data-prod="${esc(k.codigo)}">${esc(k.codigo)}</span><div class="small muted">${esc(P(k.codigo).desc)}</div>` }, { h: "Lote", f: k => `<span class="mono small">${esc(k.lote)}</span>` }, { h: "Desde", f: k => `<span class="mono small">${esc(k.from)}</span>` }, { h: "Hacia", f: k => `<span class="mono small">${esc(k.to)}</span>` }, { h: "Cantidad", a: "r", f: k => `<b class="num" style="color:${k.qty < 0 ? "var(--bad)" : "var(--ok)"}">${k.qty > 0 ? "+" : ""}${fmt(k.qty)}</b>` }, { h: "Documento", f: k => `<span class="mono small">${esc(k.doc)}</span>` }, { h: "Usuario / equipo", f: k => `${esc(userName(k.user))}<div class="small muted">${esc(k.device)}${k.offline ? ` · <span style="color:var(--warn)">enviado después</span>` : ""}</div>` }], rows, { id: "kdx", empty: "Sin movimientos en el periodo" })}`;
  } else if (sub === "conteos") {
    const cs = whCnt().sort((a, b) => b.nro - a.nro); const ira = iraSeries();
    const plan = ["A", "B", "C"].map(cl => { const days = cl === "A" ? 30 : cl === "B" ? 180 : 365; const locs = uniq(whStock().filter(s => P(s.codigo).rot === cl && !isVirtualLoc(s.loc)).map(s => s.loc)); const counted = new Set(whCnt().flatMap(c => (c.lines || []).filter(l => l.counted && l.ts && l.ts >= daysAgoISO(days)).map(l => l.loc))); const n = locs.filter(l => counted.has(l)).length; return [`Clase ${cl}`, `cada ${days === 365 ? "año" : days + " días"}`, locs.length ? Math.round(n / locs.length * 100) : 0, n, locs.length]; });
    body = `<div class="card-b"><div class="grid g-1-2"><div class="stack">
        <div class="card kpi" style="box-shadow:none"><span class="lbl">IRA del último conteo</span><span class="val">${ira.length ? String(ira[ira.length - 1]).replace(".", ",") : "—"}<small>%</small></span><span class="delta">meta 98 %</span>${sparkline(ira.length ? ira : [0])}</div>
        <div class="card" style="box-shadow:none"><div class="card-h"><h3>Plan cíclico</h3></div><div class="card-b stack small">${plan.map(([c, f, p, n, t]) => `<div><div class="row between"><b>${c}</b><span class="muted">${f} · ${n}/${t} ubic.</span></div><div class="row"><div class="bar ${p >= 80 ? "ok" : p >= 40 ? "warn" : ""}" style="flex:1"><i style="width:${p}%"></i></div><span class="num muted" style="width:36px;text-align:right">${p}%</span></div></div>`).join("")}</div></div></div>
        <div class="card" style="box-shadow:none"><div class="card-h"><h3>Conteos</h3>${can("aprobar") ? `<button class="btn sm primary" data-a="cnt-new">${ic("plus")} Nuevo conteo</button>` : ""}</div>
        ${table([{ h: "Nro", f: c => `<b class="num">${c.nro}</b>` }, { h: "Tipo", f: c => `${esc(c.tipo)}<div class="small muted">${esc(c.alcance || "")}</div>` }, { h: "Apertura", f: c => `<span class="small num">${esc(c.apertura)}</span>` }, { h: "Avance", f: c => `<div class="row"><div class="bar ${c.contadas >= c.ubic ? "ok" : ""}" style="width:80px"><i style="width:${c.ubic ? Math.round(c.contadas / c.ubic * 100) : 0}%"></i></div><span class="small num">${c.contadas}/${c.ubic}</span></div>` }, { h: "Dif.", a: "r", f: c => c.dif ? `<span class="pill warn plain num">${c.dif}</span>` : "0" }, { h: "IRA", a: "r", f: c => `<b class="num">${(iraOf(c) * 100).toFixed(1)} %</b>` }, { h: "Estado", f: c => pillFor(c.estado) }], cs, { rowAttr: c => `class="clickable" data-count="${c.nro}"`, id: "cnt", empty: "Sin conteos en este almacén" })}</div></div></div>`;
  } else if (sub === "ajustes") {
    const pend = whAdj().filter(a => a.estado === "Pendiente"); const done = whAdj().filter(a => a.estado !== "Pendiente");
    body = `<div class="card-b"><div class="grid g-1-2"><div class="card" style="box-shadow:none"><div class="card-h"><h3>Nuevo ajuste</h3></div><div class="card-b stack" id="adjForm">
      ${can("ajustar") ? `${fld("Ubicación", `<input class="input mono" name="loc" data-ac="loc" placeholder="Escanea o escribe · E1-C03-N2" autocomplete="off">`)}
      ${fld("SKU", `<input class="input mono" name="codigo" data-ac="prod" placeholder="Código o descripción" autocomplete="off">`)}
      ${fld("Lote", `<input class="input mono" name="lote" data-ac="lote" data-ac-min="0" placeholder="Lote (para faltantes, el que está en la ubicación)" autocomplete="off">`)}
      <div class="grid g-2">${fld("Tipo", `<select class="select" name="tipo">${opts(["Ajuste + (sobrante)", "Ajuste − (faltante)", "Baja por merma", "Cambio de estado"])}</select>`)}${fld("Cantidad / nuevo estado", `<input class="input num" type="number" min="0" name="qty" value="0"><select class="select" name="estado" style="margin-top:6px">${opts(["DISPONIBLE", "CUARENTENA", "BLOQUEADO"])}</select>`)}</div>
      ${fld(`Motivo <span class="muted">(obligatorio)</span>`, `<select class="select" name="motivo">${opts(["Diferencia de conteo", "Rotura / merma", "Error de recepción", "Error de picking", "Control de calidad", "Otro"])}</select>`)}
      ${fld("Observación", `<textarea class="input" name="obs" rows="2"></textarea>`)}
      <div class="small muted">${ic("lock")} Ajustes mayores a <b>${fmt(setting("tolerancia"))}</b> unidades requieren aprobación de un Encargado. El movimiento queda en el kardex con usuario, equipo y hora.</div><button class="btn primary" data-a="adj-save">Registrar ajuste</button>` : `<div class="small muted">Tu rol no permite ajustar stock.</div>`}</div></div>
      <div class="stack"><div class="card" style="box-shadow:none"><div class="card-h"><h3>Pendientes de aprobación</h3><span class="pill ${pend.length ? "warn" : "ok"}">${pend.length}</span></div>${table([{ h: "Fecha", f: a => `<span class="small">${esc(a.fecha)}</span>` }, { h: "Ubicación", f: a => `<span class="mono">${esc(a.loc)}</span>` }, { h: "SKU / lote", f: a => `<span class="mono">${esc(a.codigo)}</span><div class="small muted">${esc(a.lote || "—")}</div>` }, { h: "Ajuste", a: "r", f: a => a.tipo === "Cambio de estado" ? esc(a.obs && a.obs.startsWith("→") ? a.obs : "estado") : `<b class="num" style="color:${a.qty < 0 ? "var(--bad)" : "var(--ok)"}">${a.qty > 0 ? "+" : ""}${fmt(a.qty)}</b>` }, { h: "Motivo", f: a => esc(a.motivo) }, { h: "Solicita", f: a => esc(userName(a.user)) }, { h: "", f: a => can("aprobar") ? `<div class="row"><button class="btn sm" data-a="adj-reject" data-nro="${esc(a.nro)}">Rechazar</button><button class="btn sm primary" data-a="adj-approve" data-nro="${esc(a.nro)}">Aprobar</button></div>` : `<span class="small muted">Esperando aprobación</span>` }], pend, { empty: "No hay ajustes pendientes" })}</div>
      <div class="card" style="box-shadow:none"><div class="card-h"><h3>Historial</h3><button class="btn sm" data-a="adj-export">${ic("download")} Exportar</button></div>${table([{ h: "Nro", f: a => `<span class="mono small">${esc(a.nro)}</span>` }, { h: "Fecha", f: a => `<span class="small">${esc(a.fecha)}</span>` }, { h: "Ubicación", f: a => `<span class="mono">${esc(a.loc)}</span>` }, { h: "SKU", f: a => `<span class="mono">${esc(a.codigo)}</span>` }, { h: "Ajuste", a: "r", f: a => a.tipo === "Cambio de estado" ? "estado" : `${a.qty > 0 ? "+" : ""}${fmt(a.qty)}` }, { h: "Motivo", f: a => esc(a.motivo) }, { h: "Estado", f: a => `${pillFor(a.estado)}<div class="small muted">${esc(userName(a.aprobador))}</div>` }], done, { id: "adjh", empty: "Sin ajustes procesados" })}</div></div></div></div>`;
  } else if (sub === "abc") {
    const act = PRODUCTS.filter(p => p.estado === "ACTIVO"); const groups = ["A", "B", "C"].map(r => { const ps = act.filter(p => p.rot === r); return { r, n: ps.length, u: sum(ps, p => stockOf(p.codigo)) }; }); const totU = sum(groups, g => g.u) || 1;
    const q = fq("abcQ"), cl = fv("abcCl");
    const rows = act.filter(p => (cl === "Todos" || p.rot === cl.slice(-1)) && (!q || has(p.codigo, q) || has(p.desc, q))).map(p => ({ p, o: outs90(p.codigo) })).sort((a, b) => b.o - a.o);
    const zoneFor = code => { const s = whStock().filter(x => x.codigo === code && !isVirtualLoc(x.loc)); return s.length ? uniq(s.map(x => (R(x.rack) || {}).zona || "—")).join(", ") : "—"; };
    const zoneOk = (p, z) => z === "—" || (p.rot === "A" ? /Picking|Piso/.test(z) : p.rot === "C" ? /Volumen|Reserva/.test(z) : true);
    body = `<div class="card-b"><div class="grid g-3" style="margin-bottom:16px">${groups.map(g => `<div class="card kpi" style="box-shadow:none"><span class="lbl">Clase ${g.r} · ${g.r === "A" ? "alta rotación, cerca de picking" : g.r === "B" ? "rotación media" : "baja rotación, fondo de nave"}</span><span class="val">${g.n}<small>SKU</small></span><span class="delta">${Math.round(g.u / totU * 100)} % de las unidades en stock</span></div>`).join("")}</div>
      <div class="toolbar" style="padding:0 0 10px">${searchBox("abcQ", "SKU o descripción")}${chipBar("abcCl", ["Todos", "Clase A", "Clase B", "Clase C"])}<div style="flex:1"></div><span class="muted small">Pareto sobre salidas de 90 días (A = 80 %, B = 15 %, C = 5 %).</span>${can("maestros") ? `<button class="btn sm" data-a="abc-recalc">${ic("refresh")} Recalcular</button>` : ""}<button class="btn sm" data-a="abc-export">${ic("download")} Exportar</button></div>
      ${table([{ h: "SKU", f: r => `<span class="mono link" data-prod="${esc(r.p.codigo)}">${esc(r.p.codigo)}</span><div class="small muted">${esc(r.p.desc)}</div>` }, { h: "Clase", f: r => rotTag(r.p.rot) }, { h: "Salidas 90 d", a: "r", f: r => fmt(r.o) }, { h: "Stock", a: "r", f: r => fmt(stockOf(r.p.codigo)) }, { h: "Zona actual", f: r => { const z = zoneFor(r.p.codigo); return `${esc(z)} ${zoneOk(r.p, z) ? "" : `<span class="pill warn plain">reubicar</span>`}`; } }, { h: "Sugerencia", f: r => r.p.rot === "A" ? "Picking A / piso" : r.p.rot === "B" ? "Reserva" : "Volumen C" }], rows, { id: "abc", empty: "Sin productos" })}</div>`;
  } else {
    const q = fq("mmQ"), f = fv("mmF");
    const rows = PRODUCTS.filter(p => p.estado === "ACTIVO").map(p => ({ p, s: stockOf(p.codigo) })).filter(r => (!q || has(r.p.codigo, q) || has(r.p.desc, q)) && (f === "Todos" || (f === "Bajo mínimo" && r.s < r.p.min) || (f === "Sobre máximo" && r.p.max && r.s > r.p.max) || (f === "En rango" && r.s >= r.p.min && (!r.p.max || r.s <= r.p.max)) || (f === "Sin parámetros" && (!r.p.min || !r.p.max)))).sort((a, b) => (a.s / (a.p.min || 1)) - (b.s / (b.p.min || 1)));
    body = `<div class="toolbar">${searchBox("mmQ", "SKU o descripción")}${chipBar("mmF", ["Todos", "Bajo mínimo", "Sobre máximo", "En rango", "Sin parámetros"])}<div style="flex:1"></div><button class="btn sm" data-a="mm-proposal">${ic("zap")} Propuesta de reposición (Excel)</button></div>
      ${table([{ h: "SKU", f: r => `<span class="mono link" data-prod="${esc(r.p.codigo)}">${esc(r.p.codigo)}</span><div class="small muted">${esc(r.p.desc)}</div>` }, { h: "Clase", f: r => rotTag(r.p.rot) }, { h: "Mín", a: "r", f: r => fmt(r.p.min) }, { h: "Máx", a: "r", f: r => fmt(r.p.max) }, { h: "Stock", a: "r", f: r => `<b class="num">${fmt(r.s)}</b>` }, { h: "Cobertura", f: r => { const pct = r.p.max ? Math.min(100, Math.round(r.s / r.p.max * 100)) : 0; const k = r.s < r.p.min ? "bad" : r.p.max && r.s > r.p.max ? "warn" : "ok"; return `<div class="row"><div class="bar ${k}" style="width:120px"><i style="width:${pct}%"></i></div><span class="small num muted">${pct}%</span></div>`; } }, { h: "Situación", f: r => r.s < r.p.min ? `<span class="pill bad">Bajo mínimo</span>` : r.p.max && r.s > r.p.max ? `<span class="pill warn">Sobre máximo</span>` : `<span class="pill ok">En rango</span>` }, { h: "Días de stock", a: "r", f: r => { const d = daysOfStock(r.p.codigo); return d === null ? `<span class="muted">sin salidas</span>` : `${fmt(d)} d`; } }, { h: "", f: r => can("maestros") ? `<button class="btn sm ghost icon" data-a="prod-edit" data-cod="${esc(r.p.codigo)}" title="Editar mín/máx">${ic("edit")}</button>` : "" }], rows, { id: "mm", empty: "Sin productos con ese filtro" })}`;
  }
  return `${pageHead("Stock e inventario", `${esc(WH().name)} · saldos por ubicación, lote y estado; kardex inmutable; conteos cíclicos con aprobación.`, `<button class="btn" data-a="stock-export">${ic("download")} Exportar saldos</button>${can("reubicar") ? `<button class="btn" data-a="mv-open">${ic("move")} Reubicar</button>` : ""}${can("aprobar") ? `<button class="btn primary" data-a="cnt-new">${ic("count")} Nuevo conteo</button>` : ""}`)}
  <div class="card"><div class="tabs">${tabs.map(([k, l]) => `<button class="${sub === k ? "on" : ""}" data-sub="stock:${k}">${l}</button>`).join("")}</div>${body}</div>`;
};
ACTIONS["stock-export"] = () => exportXLSX(`stock_${state.wh}_${stamp()}`, { name: "Stock", cols: [{ h: "almacen", v: s => s.wh }, { h: "ubicacion", v: s => s.loc }, { h: "codigo", v: s => s.codigo }, { h: "descripcion", v: s => P(s.codigo).desc }, { h: "um", v: s => P(s.codigo).um }, { h: "lote", v: s => s.lote }, { h: "cantidad", v: s => s.qty }, { h: "reservado", v: s => s.reservado || 0 }, { h: "fecha_ingreso", v: s => s.ingreso }, { h: "vencimiento", v: s => s.venc || "" }, { h: "estado", v: s => s.estado }], rows: whStock() });
ACTIONS["kdx-export"] = () => { const d1 = state.filters.kdx1 || daysAgoISO(30), d2 = state.filters.kdx2 || todayISO(); exportXLSX(`kardex_${state.wh}_${d1}_${d2}`, { name: "Kardex", cols: [{ h: "fecha_hora", v: k => k.ts }, { h: "movimiento", v: k => k.tipo }, { h: "codigo", v: k => k.codigo }, { h: "descripcion", v: k => P(k.codigo).desc }, { h: "lote", v: k => k.lote }, { h: "desde", v: k => k.from }, { h: "hacia", v: k => k.to }, { h: "cantidad", v: k => k.qty }, { h: "documento", v: k => k.doc }, { h: "usuario", v: k => k.user }, { h: "equipo", v: k => k.device }, { h: "sin_conexion", v: k => k.offline ? "sí" : "no" }], rows: whKdx().filter(k => k.ts.slice(0, 10) >= d1 && k.ts.slice(0, 10) <= d2) }); };
ACTIONS["adj-export"] = () => exportXLSX(`ajustes_${state.wh}_${stamp()}`, { name: "Ajustes", cols: [{ h: "nro", v: a => a.nro }, { h: "fecha", v: a => a.fecha }, { h: "ubicacion", v: a => a.loc }, { h: "codigo", v: a => a.codigo }, { h: "lote", v: a => a.lote }, { h: "tipo", v: a => a.tipo }, { h: "cantidad", v: a => a.qty }, { h: "motivo", v: a => a.motivo }, { h: "observacion", v: a => a.obs }, { h: "solicita", v: a => a.user }, { h: "estado", v: a => a.estado }, { h: "aprobador", v: a => a.aprobador }], rows: whAdj() });
ACTIONS["abc-export"] = () => exportXLSX(`abc_${stamp()}`, { name: "ABC", cols: [{ h: "codigo", v: p => p.codigo }, { h: "descripcion", v: p => p.desc }, { h: "clase", v: p => p.rot }, { h: "salidas_90d", v: p => outs90(p.codigo) }, { h: "stock", v: p => stockOf(p.codigo) }], rows: PRODUCTS.filter(p => p.estado === "ACTIVO") });
ACTIONS["abc-recalc"] = b => run(b, async () => {
  const act = PRODUCTS.filter(p => p.estado === "ACTIVO").map(p => ({ p, o: outs90(p.codigo) })).sort((a, b) => b.o - a.o); const tot = sum(act, x => x.o);
  if (!tot) throw new Error("No hay salidas en los últimos 90 días para calcular la clasificación.");
  let acc = 0; const changed = [];
  act.forEach(x => { acc += x.o; const cls = x.o === 0 ? "C" : acc / tot <= .8 || acc - x.o === 0 ? "A" : acc / tot <= .95 ? "B" : "C"; if (x.p.rot !== cls) { x.p.rot = cls; changed.push(x.p); } });
  if (!await confirmDlg("Recalcular ABC", `Cambiarán de clase <b>${changed.length}</b> producto(s).`, { ok: "Aplicar" })) { await resync(true); render(); return; }
  await saveMany("PRODUCTS", changed); render(); toast(`Clasificación ABC recalculada: ${changed.length} cambio(s).`);
});
ACTIONS["mm-proposal"] = () => { const rows = PRODUCTS.filter(p => p.estado === "ACTIVO" && p.min > 0 && stockOf(p.codigo) < p.min); if (!rows.length) { toast("Ningún producto está bajo el mínimo.", "info"); return; } exportXLSX(`propuesta_reposicion_${state.wh}_${stamp()}`, { name: "Reposición", cols: [{ h: "codigo", v: p => p.codigo }, { h: "descripcion", v: p => p.desc }, { h: "um", v: p => p.um }, { h: "clase", v: p => p.rot }, { h: "stock", v: p => stockOf(p.codigo) }, { h: "minimo", v: p => p.min }, { h: "maximo", v: p => p.max }, { h: "cantidad_sugerida", v: p => Math.max(0, (p.max || p.min * 2) - stockOf(p.codigo)) }, { h: "salidas_90d", v: p => outs90(p.codigo) }], rows }); };

/* ---------------------------------------------------- reubicar (escritorio) */
ACTIONS["mv-open"] = b => {
  const d = b?.dataset || {};
  openModal("Reubicar stock", `<p class="muted" style="margin:0 0 12px">Mueve unidades entre ubicaciones del almacén <b>${esc(state.wh)}</b>. Queda en el kardex como «Reubicación».</p>
    <div class="grid g-2">${fld("Ubicación de origen", `<input class="input mono" name="from" data-ac="locstock" data-ac-min="0" value="${esc(d.loc || "")}" placeholder="Ubicación, SKU o lote" autocomplete="off">`)}${fld("Saldo a mover", `<select class="select" name="sid" id="mvSid"></select>`)}${fld("Cantidad", `<input class="input num" type="number" min="1" name="qty" id="mvQty">`)}${fld("Ubicación de destino", `<input class="input mono" name="to" data-ac="loc" placeholder="Escanea o escribe" autocomplete="off">`)}</div>`,
    `<button class="btn" data-close>Cancelar</button><button class="btn primary" data-a="mv-ok">${ic("move")} Reubicar</button>`,
    { onOpen: box => { const fill = () => { const loc = $("[name=from]", box).value.trim(); const rows = whStock().filter(s => s.loc === loc); $("#mvSid").innerHTML = rows.length ? rows.map((s, i) => opt(i, rows.findIndex(r => r.codigo === d.cod && (r.lote || "") === (d.lote || "")), `${s.codigo} · lote ${s.lote || "—"} · ${fmt(s.qty - (s.reservado || 0))} libres`)).join("") : `<option value="">— sin saldo en esa ubicación —</option>`; const s = rows[+$("#mvSid").value]; $("#mvQty").value = s ? s.qty - (s.reservado || 0) : ""; }; fill(); $("[name=from]", box).addEventListener("change", fill); $("#mvSid").addEventListener("change", () => { const rows = whStock().filter(s => s.loc === $("[name=from]", box).value.trim()); const s = rows[+$("#mvSid").value]; $("#mvQty").value = s ? s.qty - (s.reservado || 0) : ""; }); } });
};
ACTIONS["mv-ok"] = b => run(b, async () => {
  const v = formVals($("#modalBox")); const rows = whStock().filter(s => s.loc === v.from); const s = rows[+v.sid];
  if (!s) throw new Error("Elige un saldo de origen."); const to = L(v.to);
  if (!to || (to.wh || "BOL2") !== state.wh) throw new Error("La ubicación de destino no existe en este almacén.");
  if (to.blocked) throw new Error(`La ubicación ${to.id} está bloqueada.`); if (to.id === s.loc) throw new Error("Origen y destino son la misma ubicación.");
  const q = Math.round(v.qty || 0); if (q <= 0 || q > s.qty - (s.reservado || 0)) throw new Error(`Cantidad inválida: hay ${fmt(s.qty - (s.reservado || 0))} un. libres.`);
  await mov([{ tipo: "Reubicación", dir: "mv", codigo: s.codigo, lote: s.lote, qty: q, from: s.loc, to: to.id, doc: nextNro("MOV", KARDEX, "doc") }]);
  closeModal(); render(); if (state.drawerFn) state.drawerFn(); toast(`Reubicado ${fmt(q)} × ${esc(s.codigo)}: ${esc(s.loc)} → ${esc(to.id)}.`);
});

/* ---------------------------------------------------- ajustes */
ACTIONS["adj-save"] = b => run(b, async () => {
  const v = formVals($("#adjForm")); const loc = L(v.loc);
  if (!loc || (loc.wh || "BOL2") !== state.wh) throw new Error("La ubicación no existe en este almacén.");
  if (!PRODUCTS.some(p => p.codigo === v.codigo)) throw new Error("El producto no existe.");
  const neg = v.tipo !== "Ajuste + (sobrante)" && v.tipo !== "Cambio de estado"; const st = whStock().find(s => s.loc === loc.id && s.codigo === v.codigo && (!v.lote || s.lote === v.lote));
  if ((neg || v.tipo === "Cambio de estado") && !st) throw new Error(`No hay saldo de ${v.codigo}${v.lote ? " lote " + v.lote : ""} en ${loc.id}.`);
  const q = Math.round(v.qty || 0); if (v.tipo !== "Cambio de estado" && q <= 0) throw new Error("Indica la cantidad.");
  if (neg && q > st.qty) throw new Error(`Solo hay ${fmt(st.qty)} un. en la ubicación.`);
  const a = { nro: nextNro("AJ", AJUSTES), fecha: nowHuman(), wh: state.wh, loc: loc.id, codigo: v.codigo, lote: st ? st.lote : (v.lote || lotCode()), tipo: v.tipo === "Cambio de estado" ? "Cambio de estado" : neg ? (v.tipo === "Baja por merma" ? "Baja por merma" : "Ajuste −") : "Ajuste +", qty: v.tipo === "Cambio de estado" ? 0 : neg ? -q : q, motivo: v.motivo, obs: v.tipo === "Cambio de estado" ? `→ ${v.estado}${v.obs ? " · " + v.obs : ""}` : v.obs || null, user: me(), estado: "Pendiente", aprobador: null, doc: null };
  const auto = v.tipo !== "Cambio de estado" ? Math.abs(a.qty) <= +setting("tolerancia") : can("aprobar");
  if (auto) await applyAdjust(a, v.tipo === "Cambio de estado" ? v.estado : null); else await save("AJUSTES", a);
  render(); toast(auto ? `Ajuste ${esc(a.nro)} aplicado al saldo.` : `Ajuste ${esc(a.nro)} enviado a aprobación.`, auto ? "ok" : "info");
});
async function applyAdjust(a, newEstado) {
  if (a.tipo === "Cambio de estado") await mov([{ tipo: "Cambio de estado", dir: "mv", codigo: a.codigo, lote: a.lote, qty: 0, from: a.loc, to: a.loc, estado: newEstado || String(a.obs || "").replace("→ ", "").split(" · ")[0], doc: a.nro }], a.wh);
  else await mov([a.qty > 0 ? { tipo: "Ajuste +", dir: "in", codigo: a.codigo, lote: a.lote, qty: a.qty, from: "AJUSTE", to: a.loc, doc: a.nro } : { tipo: a.tipo === "Baja por merma" ? "Baja por merma" : "Ajuste −", dir: "out", codigo: a.codigo, lote: a.lote, qty: -a.qty, from: a.loc, to: "AJUSTE", doc: a.nro }], a.wh);
  a.estado = "Aprobado"; a.aprobador = me(); a.doc = a.nro; await save("AJUSTES", a);
}
ACTIONS["adj-approve"] = b => run(b, async () => { const a = AJUSTES.find(x => x.nro === b.dataset.nro); await applyAdjust(a); render(); toast(`Ajuste ${esc(a.nro)} aprobado y aplicado al saldo.`); });
ACTIONS["adj-reject"] = b => run(b, async () => { const a = AJUSTES.find(x => x.nro === b.dataset.nro); const v = await dialog("Rechazar ajuste", fld("Motivo del rechazo", `<textarea class="input" name="m" rows="2"></textarea>`), { ok: "Rechazar", danger: true }); if (!v) return; a.estado = "Rechazado"; a.aprobador = me(); a.obs = `${a.obs ? a.obs + " · " : ""}Rechazo: ${v.m || "sin motivo"}`; await save("AJUSTES", a); render(); toast("Ajuste rechazado.", "info"); });
document.addEventListener("ac:pick", e => { const f = e.target.closest("#adjForm"); if (!f) return; const loc = $("[name=loc]", f).value, cod = $("[name=codigo]", f).value; const lt = $("[name=lote]", f); lt.dataset.acLoc = loc; lt.dataset.acProd = cod; if (e.target.name !== "lote") { const s = whStock().filter(x => x.loc === loc && x.codigo === cod); if (s.length === 1) lt.value = s[0].lote || ""; } });

/* ---------------------------------------------------- conteos */
function countScope(v) {
  const locs = whLocs().filter(l => !isVirtualLoc(l.id));
  if (v.tipo === "Por rack") return locs.filter(l => l.rack === v.rack);
  if (v.tipo === "Por producto") return locs.filter(l => STOCK.some(s => s.loc === l.id && s.codigo === v.prod));
  if (v.tipo.startsWith("Cíclico")) { const cl = v.tipo.slice(-1); return locs.filter(l => STOCK.some(s => s.loc === l.id && P(s.codigo).rot === cl)); }
  if (v.tipo === "Por ubicación") return (v.locs || "").split(/[\s,;]+/).map(x => L(x.trim().toUpperCase())).filter(l => l && (l.wh || "BOL2") === state.wh);
  if (v.tipo === "General") return locs;
  return [];
}
ACTIONS["cnt-new"] = () => {
  const ops = whUsersCol();
  openModal("Nuevo conteo de inventario", `<div class="grid g-3" style="margin-bottom:14px">${fld("Tipo", `<select class="select" name="tipo" id="cntTipo">${opts(["Cíclico clase A", "Cíclico clase B", "Cíclico clase C", "Por rack", "Por producto", "Por ubicación", "General"])}</select>`)}${fld("Modalidad", `<select class="select" name="modalidad">${opts(["Ciego (sin cantidad esperada)", "Con cantidad esperada"])}</select>`)}${fld("Responsable", `<select class="select" name="resp">${ops.map(u => opt(u.user, "", u.nombre)).join("")}${USERS_DESK.filter(u => u.estado === "HABILITADO" && u.wh.includes(state.wh)).map(u => opt(u.user, me(), u.nombre + " (escritorio)")).join("")}</select>`)}</div>
    <div class="grid g-2"><div id="cntScope">${fld("Rack", `<select class="select" name="rack">${whRacks().filter(r => !VIRTUAL_ZONES.includes(r.zona)).map(r => opt(r.id, "", `${r.id} · ${r.name}`)).join("")}</select>`, "sc sc-rack")}${fld("Producto", `<input class="input mono" name="prod" data-ac="prod" autocomplete="off" placeholder="Código o descripción">`, "sc sc-prod")}${fld("Ubicaciones (separadas por coma o espacio)", `<textarea class="input mono" name="locs" rows="3" placeholder="E1-C01-N1, E1-C01-N2"></textarea>`, "sc sc-loc")}<p class="small muted" id="cntCount" style="margin:6px 0 0"></p></div>
    <div class="stack"><div class="row"><button class="tog on" type="button" data-tog="bloquear"></button><span class="small">Bloquear picking en las ubicaciones mientras se cuentan</span></div><p class="small muted" style="margin:0">El conteo aparece en los colectores del almacén. Las diferencias se aprueban aquí y generan ajustes en el kardex.</p></div></div>`,
    `<button class="btn" data-close>Cancelar</button><button class="btn primary" data-a="cnt-save">${ic("count")} Habilitar conteo</button>`,
    { onOpen: box => { const upd = () => { const v = formVals(box); $$(".sc", box).forEach(x => x.hidden = true); if (v.tipo === "Por rack") $(".sc-rack", box).hidden = false; if (v.tipo === "Por producto") $(".sc-prod", box).hidden = false; if (v.tipo === "Por ubicación") $(".sc-loc", box).hidden = false; $("#cntCount").textContent = `${countScope(v).length} ubicaciones a contar`; }; upd(); box.addEventListener("change", upd); box.addEventListener("input", e => { if (e.target.name === "locs") upd(); }); } });
};
ACTIONS["cnt-save"] = b => run(b, async () => {
  const v = formVals($("#modalBox")); const scope = countScope(v); if (!scope.length) throw new Error("El alcance no tiene ubicaciones.");
  const c = { nro: Math.max(0, ...CONTEOS.map(x => +x.nro)) + 1, tipo: v.tipo, wh: state.wh, apertura: nowHuman(), estado: "Habilitado", ubic: scope.length, contadas: 0, dif: 0, resp: v.resp || me(), ira: 0, alcance: v.tipo === "Por rack" ? `Rack ${v.rack}` : v.tipo === "Por producto" ? v.prod : v.tipo === "Por ubicación" ? `${scope.length} ubicaciones` : v.tipo, modalidad: v.modalidad, bloquear: v.bloquear, lines: scope.sort((a, b) => a.sort - b.sort).map(l => ({ loc: l.id, items: STOCK.filter(s => s.loc === l.id).map(s => ({ codigo: s.codigo, lote: s.lote, sys: s.qty })), counted: false, conteo: [], user: null, ts: null })) };
  await save("CONTEOS", c); closeOverlays(); state.sub.stock = "conteos"; go("stock"); DETAIL.count(c.nro); toast(`Conteo ${c.nro} habilitado: ${c.ubic} ubicaciones. Ya aparece en los colectores.`);
});
DETAIL.count = nro => {
  const c = CONTEOS.find(x => +x.nro === +nro); if (!c) return; const lines = c.lines || [];
  const difs = lines.flatMap(l => lineDiff(l).map(d => ({ ...d, loc: l.loc, user: l.user })));
  const open = ["Habilitado", "En curso"].includes(c.estado);
  const foot = `${lines.length ? `<button class="btn" data-a="cnt-export" data-nro="${c.nro}">${ic("download")} ${c.estado === "Finalizado" ? "Informe" : "Exportar"}</button>` : ""}${open && can("aprobar") ? `<button class="btn danger" data-a="cnt-cancel" data-nro="${c.nro}">Anular</button><button class="btn" data-a="cnt-col" data-nro="${c.nro}">${ic("phone")} Contar en colector</button><button class="btn primary" data-a="cnt-close" data-nro="${c.nro}">${difs.length ? "Aprobar diferencias y finalizar" : "Finalizar conteo"}</button>` : `<button class="btn primary" data-close>Cerrar</button>`}`;
  openDrawer(`Conteo ${c.nro} · ${esc(c.tipo)}`, `<div class="grid g-3" style="margin-bottom:16px"><div class="card kpi" style="box-shadow:none"><span class="lbl">Avance</span><span class="val">${c.ubic ? Math.round(c.contadas / c.ubic * 100) : 0}<small>%</small></span><span class="delta">${c.contadas} de ${c.ubic} ubicaciones</span></div><div class="card kpi" style="box-shadow:none"><span class="lbl">Diferencias</span><span class="val">${lines.length ? difs.length : c.dif}</span><span class="delta">${c.estado === "Finalizado" ? "ajustadas" : "pendientes de aprobar"}</span></div><div class="card kpi" style="box-shadow:none"><span class="lbl">IRA ${c.estado === "Finalizado" ? "final" : "parcial"}</span><span class="val">${(iraOf(c) * 100).toFixed(1)}<small>%</small></span><span class="delta">meta 98 %</span></div></div>
    ${lines.length ? `<h3 style="font-size:14px;margin-bottom:8px">Ubicaciones con diferencia</h3>${table([{ h: "Ubicación", f: d => `<span class="mono">${esc(d.loc)}</span>` }, { h: "SKU / lote", f: d => `<span class="mono small">${esc(d.codigo)}</span><div class="small muted">${esc(d.lote)}</div>` }, { h: "Sistema", a: "r", f: d => fmt(d.sys) }, { h: "Contado", a: "r", f: d => `<b class="num">${fmt(d.cnt)}</b>` }, { h: "Dif.", a: "r", f: d => `<span class="pill ${d.dif < 0 ? "bad" : "warn"} plain num">${d.dif > 0 ? "+" : ""}${fmt(d.dif)}</span>` }, { h: "", f: d => open && can("aprobar") ? `<button class="btn sm" data-a="cnt-recount" data-nro="${c.nro}" data-loc="${esc(d.loc)}">Recontar</button>` : "" }], difs, { empty: c.contadas ? "Sin diferencias hasta ahora" : "Aún no se contó ninguna ubicación" })}
    <h3 style="font-size:14px;margin:16px 0 8px">Ubicaciones</h3>${table([{ h: "Ubicación", f: l => `<span class="mono">${esc(l.loc)}</span>` }, { h: "Estado", f: l => l.counted ? (lineDiff(l).length ? `<span class="pill warn">Con diferencia</span>` : `<span class="pill ok">OK</span>`) : `<span class="pill neutral">Pendiente</span>` }, { h: "Contó", f: l => l.counted ? `${esc(userName(l.user))}<div class="small muted">${esc(l.ts || "")}</div>` : "—" }, { h: "", f: l => open && (can("aprobar") || can("ajustar")) ? `<button class="btn sm ghost" data-a="cnt-desk" data-nro="${c.nro}" data-loc="${esc(l.loc)}">${l.counted ? "Corregir" : "Registrar"}</button>` : "" }], lines, { id: "cntl" + c.nro, page: 12 })}` : `<div class="card" style="box-shadow:none"><div class="card-b small muted">${ic("history")} Conteo histórico cargado sin detalle por ubicación.</div></div>`}
    <dl class="kv" style="margin-top:16px"><dt>Responsable</dt><dd>${esc(userName(c.resp))}</dd><dt>Apertura</dt><dd>${esc(c.apertura)}</dd><dt>Modalidad</dt><dd>${esc(c.modalidad || "—")}</dd><dt>Bloqueo de picking</dt><dd>${c.bloquear ? "Sí, mientras se cuenta" : "No"}</dd><dt>Estado</dt><dd>${pillFor(c.estado)}</dd></dl>`, foot, "Inventario cíclico");
  state.drawerFn = () => DETAIL.count(nro);
};
function recalcCount(c) { const ls = c.lines || []; c.contadas = ls.filter(l => l.counted).length; c.dif = ls.filter(l => lineDiff(l).length).length; c.ira = iraOf(c); if (c.estado === "Habilitado" && c.contadas) c.estado = "En curso"; }
/** Registra el conteo de una ubicación. conteo: [{codigo, lote, qty}] */
async function recordCount(c, loc, conteo) { const l = c.lines.find(x => x.loc === loc); l.conteo = conteo.filter(x => x.qty > 0 || l.items.some(i => i.codigo === x.codigo && i.lote === x.lote)); l.counted = true; l.user = me(); l.ts = nowTS(); recalcCount(c); await save("CONTEOS", c); }
ACTIONS["cnt-desk"] = b => {
  const c = CONTEOS.find(x => +x.nro === +b.dataset.nro); const l = c.lines.find(x => x.loc === b.dataset.loc); const blind = /Ciego/.test(c.modalidad || "");
  const rows = uniq([...l.items.map(i => `${i.codigo}|${i.lote}`), ...(l.conteo || []).map(i => `${i.codigo}|${i.lote}`)]).map(k => { const [codigo, lote] = k.split("|"); return { codigo, lote, sys: sum(l.items.filter(i => i.codigo === codigo && String(i.lote) === lote), i => i.sys), cnt: (l.conteo || []).find(i => i.codigo === codigo && String(i.lote) === lote)?.qty }; });
  openModal(`Conteo ${c.nro} · ${esc(l.loc)}`, `<table class="tbl"><thead><tr><th>SKU</th><th>Lote</th>${blind ? "" : `<th class="r">Sistema</th>`}<th class="r">Contado</th></tr></thead><tbody id="cntRows">${rows.map(r => `<tr class="ln"><td><input type="hidden" name="codigo" value="${esc(r.codigo)}"><span class="mono">${esc(r.codigo)}</span><div class="small muted">${esc(P(r.codigo).desc)}</div></td><td><input type="hidden" name="lote" value="${esc(r.lote)}"><span class="mono small">${esc(r.lote)}</span></td>${blind ? "" : `<td class="r">${fmt(r.sys)}</td>`}<td class="r"><input class="input num" type="number" min="0" name="qty" value="${r.cnt ?? ""}" style="width:100px;text-align:right"></td></tr>`).join("")}</tbody></table>
    <div class="grid g-3" style="margin-top:12px;align-items:end">${fld("Agregar ítem encontrado", `<input class="input mono" id="cntAddCod" data-ac="prod" autocomplete="off" placeholder="SKU">`)}${fld("Lote", `<input class="input mono" id="cntAddLote" placeholder="Lote">`)}<button class="btn" type="button" data-a="cnt-addrow" data-blind="${blind ? 1 : 0}">${ic("plus")} Agregar</button></div>`,
    `<button class="btn" data-close>Cancelar</button><button class="btn primary" data-a="cnt-desk-ok" data-nro="${c.nro}" data-loc="${esc(l.loc)}">${ic("check")} Guardar conteo</button>`);
};
ACTIONS["cnt-addrow"] = b => { const cod = $("#cntAddCod").value.trim(); if (!PRODUCTS.some(p => p.codigo === cod)) { toast("Elige un producto válido.", "bad"); return; } const lote = $("#cntAddLote").value.trim() || "S/L"; $("#cntRows").insertAdjacentHTML("beforeend", `<tr class="ln"><td><input type="hidden" name="codigo" value="${esc(cod)}"><span class="mono">${esc(cod)}</span><div class="small muted">${esc(P(cod).desc)}</div></td><td><input type="hidden" name="lote" value="${esc(lote)}"><span class="mono small">${esc(lote)}</span></td>${b.dataset.blind === "1" ? "" : `<td class="r">0</td>`}<td class="r"><input class="input num" type="number" min="0" name="qty" style="width:100px;text-align:right"></td></tr>`); $("#cntAddCod").value = ""; $("#cntAddLote").value = ""; };
ACTIONS["cnt-desk-ok"] = b => run(b, async () => { const c = CONTEOS.find(x => +x.nro === +b.dataset.nro); const conteo = $$("#cntRows tr.ln").map(tr => { const v = formVals(tr); return { codigo: v.codigo, lote: v.lote, qty: Math.round(v.qty || 0) }; }); await recordCount(c, b.dataset.loc, conteo); closeModal(); render(); DETAIL.count(c.nro); toast(`Ubicación ${esc(b.dataset.loc)} contada.`); });
ACTIONS["cnt-recount"] = b => run(b, async () => { const c = CONTEOS.find(x => +x.nro === +b.dataset.nro); const l = c.lines.find(x => x.loc === b.dataset.loc); l.counted = false; l.conteo = []; l.user = null; l.ts = null; recalcCount(c); await save("CONTEOS", c); render(); DETAIL.count(c.nro); toast(`Recuento solicitado: ${esc(l.loc)} vuelve a pendientes en el colector.`, "info"); });
ACTIONS["cnt-col"] = b => { closeOverlays(); openCollector(); col.cnt = +b.dataset.nro; col.screen = "conteo"; col.from = null; cRender(); };
ACTIONS["cnt-cancel"] = b => run(b, async () => { const c = CONTEOS.find(x => +x.nro === +b.dataset.nro); if (!await confirmDlg("Anular conteo", "Se descarta lo contado y se liberan las ubicaciones bloqueadas.", { ok: "Anular", danger: true })) return; c.estado = "Anulado"; await save("CONTEOS", c); render(); DETAIL.count(c.nro); toast("Conteo anulado.", "info"); });
ACTIONS["cnt-close"] = b => run(b, async () => {
  const c = CONTEOS.find(x => +x.nro === +b.dataset.nro); const pend = c.lines.filter(l => !l.counted).length;
  const difs = c.lines.flatMap(l => lineDiff(l).map(d => ({ ...d, loc: l.loc })));
  if (!await confirmDlg("Finalizar conteo", `${pend ? `<b>${pend}</b> ubicación(es) sin contar quedarán fuera. ` : ""}${difs.length ? `Se aplicarán <b>${difs.length}</b> ajuste(s) al stock (${fmt(sum(difs, d => d.dif))} un. netas) a tu nombre.` : "No hay diferencias."}`, { ok: "Finalizar" })) return;
  const movs = difs.map(d => d.dif > 0 ? { tipo: "Ajuste +", dir: "in", codigo: d.codigo, lote: d.lote, qty: d.dif, from: `CONTEO-${c.nro}`, to: d.loc, doc: `CNT-${c.nro}` } : { tipo: "Ajuste −", dir: "out", codigo: d.codigo, lote: d.lote, qty: -d.dif, from: d.loc, to: `CONTEO-${c.nro}`, doc: `CNT-${c.nro}` });
  if (movs.length) await mov(movs, c.wh);
  c.lines = c.lines.filter(l => l.counted); recalcCount(c); c.ubic = c.lines.length || c.ubic; c.estado = "Finalizado"; await save("CONTEOS", c);
  render(); DETAIL.count(c.nro); toast(`Conteo ${c.nro} finalizado · IRA ${(c.ira * 100).toFixed(1)} %${movs.length ? ` · ${movs.length} ajuste(s) aplicados` : ""}.`);
});
ACTIONS["cnt-export"] = b => { const c = CONTEOS.find(x => +x.nro === +b.dataset.nro); const rows = c.lines.flatMap(l => { const keys = uniq([...l.items.map(i => `${i.codigo}|${i.lote}`), ...(l.conteo || []).map(i => `${i.codigo}|${i.lote}`)]); return keys.length ? keys.map(k => { const [codigo, lote] = k.split("|"); const sys = sum(l.items.filter(i => i.codigo === codigo && String(i.lote) === lote), i => i.sys); const cnt = l.counted ? sum((l.conteo || []).filter(i => i.codigo === codigo && String(i.lote) === lote), i => i.qty) : ""; return [l.loc, codigo, P(codigo).desc, lote, sys, cnt, l.counted ? cnt - sys : "", l.counted ? "Contada" : "Pendiente", l.user || "", l.ts || ""]; }) : [[l.loc, "", "(vacía)", "", 0, l.counted ? 0 : "", l.counted ? 0 : "", l.counted ? "Contada" : "Pendiente", l.user || "", l.ts || ""]]; }); exportXLSX(`conteo_${c.nro}`, { name: `Conteo ${c.nro}`, aoa: [["ubicacion", "codigo", "descripcion", "lote", "sistema", "contado", "diferencia", "estado", "usuario", "fecha"], ...rows] }); };

/* ===================================================================== MAPA DE ALMACÉN */
VIEWS.ubicaciones = () => {
  const racks = whRacks(); const wh = WH();
  if (!racks.length) return `${pageHead("Mapa de almacén", `${esc(wh.name)} · aún no tiene racks ni áreas.`, can("maestros") ? `<button class="btn primary" data-a="rack-new">${ic("plus")} Nuevo rack / área</button>` : "")}<div class="card"><div class="empty">${ic("map")}<div>Crea el primer rack o área (incluye un <b>Muelle de ingreso</b> con zona «Recepción» para poder recibir), o impórtalos desde Excel.</div><div class="row" style="justify-content:center;margin-top:12px;gap:8px">${can("maestros") ? `<button class="btn primary" data-a="rack-new">${ic("plus")} Nuevo rack / área</button>` : ""}<button class="btn" data-a="imp-open" data-ds="racks">${ic("upload")} Importar racks</button></div></div></div>`;
  let rack = state.sub.ubicaciones; if (!racks.some(r => r.id === rack)) rack = racks[0].id;
  const r = R(rack); const ls = LOCATIONS.filter(l => l.rack === rack);
  const filas = Math.max(r.filas || 1, ...ls.map(l => l.fila)), cols = Math.max(r.cols || 1, ...ls.map(l => l.col));
  const cells = []; for (let f = filas; f >= 1; f--) for (let c = 1; c <= cols; c++) { const l = ls.find(x => x.fila === f && x.col === c); if (!l) { cells.push(`<div class="cell" style="opacity:.25;border-style:dashed" title="Sin ubicación"></div>`); continue; } const o = occupancy(l); cells.push(`<div class="cell ${heat(o)} ${l.blocked ? "blocked" : ""} ${state.selLoc === l.id ? "sel" : ""}" data-cell="${esc(l.id)}" title="${esc(l.id)} · ${Math.round(o * 100)} %"></div>`); }
  const sel = state.selLoc && L(state.selLoc); const selStock = sel ? STOCK.filter(s => s.loc === sel.id) : [];
  const occ = ls.filter(l => STOCK.some(s => s.loc === l.id)).length; const m = can("maestros");
  return `${pageHead("Mapa de almacén", `${esc(wh.name)} · almacén → rack/área → ubicación. Las ubicaciones con historial no se reutilizan.`, `<button class="btn" data-a="loc-labels" data-rack="${esc(rack)}">${ic("print")} Etiquetas del rack</button>${m ? `<button class="btn" data-a="rack-new">${ic("plus")} Nuevo rack / área</button><button class="btn primary" data-a="loc-new" data-rack="${esc(rack)}">${ic("plus")} Nueva ubicación</button>` : ""}`)}
  <div class="grid map-grid">
    <div class="card"><div class="card-h"><h3>Topología</h3></div><div class="card-b" style="padding:8px"><ul class="tree"><li><div class="node">${ic("layers")}<b>${esc(wh.name)}</b></div><ul><li><div class="node">${ic("stock")}Bodega ${esc((wh.bodegas || [wh.id])[0])} <span class="cnt">${fmt(whLocs().length)}</span></div><ul>${racks.map(x => `<li><div class="node ${x.id === rack ? "on" : ""}" data-rack="${esc(x.id)}">${ic("grid")}<span>${esc(x.id)} · ${esc(x.name)}</span><span class="cnt">${LOCATIONS.filter(l => l.rack === x.id).length}</span></div></li>`).join("")}</ul></li></ul></li></ul></div></div>
    <div class="card"><div class="card-h"><div><h3>${esc(r.id)} · ${esc(r.name)}</h3><span class="muted small">${esc(r.zona)} · ${filas} niveles × ${cols} columnas · ${occ}/${ls.length} ocupadas</span></div><div class="row">${m ? `<button class="btn sm ghost" data-a="rack-edit" data-rack="${esc(r.id)}">${ic("edit")} Editar rack</button>` : ""}<div class="legend"><span><i style="background:var(--heat-1);border:1px solid var(--line)"></i>vacía</span><span><i style="background:var(--heat-3)"></i>parcial</span><span><i style="background:var(--heat-5)"></i>llena</span><span><i style="background:repeating-linear-gradient(45deg,var(--bad-soft),var(--bad-soft) 3px,transparent 3px,transparent 6px);border:1px solid var(--bad)"></i>bloqueada</span></div></div></div>
      <div class="card-b"><div class="row" style="align-items:stretch;gap:8px"><div class="stack" style="justify-content:space-around;gap:0;font-size:11px;color:var(--ink-3);text-align:right;padding:0 2px">${Array.from({ length: filas }, (_, i) => `<span>N${filas - i}</span>`).join("")}</div><div class="rackmap" style="grid-template-columns:repeat(${cols},minmax(0,1fr));flex:1">${cells.join("")}</div></div><div class="row" style="gap:4px;margin-top:6px;padding-left:28px;font-size:11px;color:var(--ink-3)">${Array.from({ length: cols }, (_, i) => `<span style="flex:1;text-align:center">C${pad(i + 1)}</span>`).join("")}</div>
      <hr class="sep"><div class="grid g-3 small"><div><div class="muted">Formato de código</div><b class="mono">${esc(setting("formatoUbic"))}</b> <span class="muted">· ej. ${esc(ls[0]?.id || "—")}</span></div><div><div class="muted">Capacidad por ubicación</div><b>${ls[0]?.cap || r.cap || 6} pallets/bultos</b></div><div><div class="muted">Orden de recorrido</div><b>Serpentina por columna</b> <span class="muted">(sort_seq)</span></div></div></div></div>
    <div class="card"><div class="card-h"><h3>${sel ? `<span class="mono">${esc(sel.id)}</span>` : "Ubicación"}</h3>${sel ? pillFor(sel.blocked ? "Bloqueada" : selStock.length ? "Ocupada" : "Vacía") : ""}</div><div class="card-b">${sel ? `<dl class="kv small" style="margin-bottom:12px"><dt>Rack</dt><dd>${esc(sel.rack)} · ${esc(r.name)}</dd><dt>Columna / nivel</dt><dd>C${pad(sel.col)} · N${sel.fila}</dd><dt>Tipo</dt><dd>${esc(sel.tipo || r.tipo || "—")}</dd><dt>Capacidad</dt><dd>${sel.cap}</dd><dt>Ocupación</dt><dd>${Math.round(occupancy(sel) * 100)} %</dd><dt>Recorrido</dt><dd class="num">#${sel.sort}</dd></dl>${selStock.length ? `<div class="stack">${selStock.map(s => `<div class="cline"><div><b class="mono small link" data-prod="${esc(s.codigo)}">${esc(s.codigo)}</b><span>${esc(P(s.codigo).desc)}<br>lote ${esc(s.lote || "—")} · ${fmtD(s.ingreso)}${s.reservado ? ` · ${fmt(s.reservado)} res.` : ""}</span></div><span class="q">${fmt(s.qty)}</span></div>`).join("")}</div>` : `<div class="empty" style="padding:20px">${ic("box")}<div>Sin stock en esta ubicación</div></div>`}<div class="stack" style="margin-top:12px"><button class="btn block" data-a="loc-label" data-loc="${esc(sel.id)}">${ic("print")} Imprimir etiqueta QR</button>${selStock.length && can("reubicar") ? `<button class="btn block" data-a="mv-open" data-loc="${esc(sel.id)}">${ic("move")} Reubicar stock</button>` : ""}${can("aprobar") || m ? `<button class="btn block" data-a="loc-block" data-loc="${esc(sel.id)}">${ic("lock")} ${sel.blocked ? "Desbloquear" : "Bloquear"} ubicación</button>` : ""}${m ? `<button class="btn block" data-a="loc-edit" data-loc="${esc(sel.id)}">${ic("edit")} Editar</button>${!selStock.length && !KARDEX.some(k => k.from === sel.id || k.to === sel.id) ? `<button class="btn block danger" data-a="loc-del" data-loc="${esc(sel.id)}">${ic("trash")} Eliminar</button>` : ""}` : ""}</div>` : `<div class="empty">${ic("map")}<div>Selecciona una celda del rack para ver su contenido</div></div>`}</div></div>
  </div>`;
};
ACTIONS["loc-block"] = b => run(b, async () => { const l = L(b.dataset.loc); l.blocked = !l.blocked; await save("LOCATIONS", l); render(); toast(`Ubicación ${esc(l.id)} ${l.blocked ? "bloqueada" : "desbloqueada"} para picking.`, l.blocked ? "info" : "ok"); });
ACTIONS["loc-label"] = b => printLabels("ubicacion", [locSample(L(b.dataset.loc))], `Etiqueta ${b.dataset.loc}`);
ACTIONS["loc-labels"] = b => printLabels("ubicacion", LOCATIONS.filter(l => l.rack === b.dataset.rack).sort((a, c) => a.col - c.col || a.fila - c.fila).map(locSample), `Etiquetas rack ${b.dataset.rack}`);
ACTIONS["loc-del"] = b => run(b, async () => { if (!await confirmDlg("Eliminar ubicación", `Se eliminará <b>${esc(b.dataset.loc)}</b>.`, { ok: "Eliminar", danger: true })) return; await del("LOCATIONS", b.dataset.loc); state.selLoc = null; render(); toast("Ubicación eliminada.", "info"); });
function rackModal(r = null) {
  const suggest = (() => { if (r) return r.id; const pre = state.wh === "BOL2" ? "E" : `${state.wh}-E`; let n = 1; while (RACKS.some(x => x.id === pre + n)) n++; return pre + n; })();
  openModal(r ? `Editar rack ${esc(r.id)}` : "Nuevo rack / área", `<div class="grid g-2">${fld("Almacén", `<input class="input" value="${esc(WH().name)}" readonly>`)}${fld("Tipo", `<select class="select" name="tipo">${opts(["Rack (estantería)", "Área de piso", "Muelle", "Zona virtual (ajustes, tránsito)"], r?.tipo)}</select>`)}${fld("Código", `<input class="input mono" name="id" value="${esc(suggest)}" ${r ? "readonly" : ""}>`)}${fld("Descripción", inp("name", r?.name || (r ? "" : `Estante ${suggest.replace(/\D/g, "")}`)))}${fld("Niveles (filas)", `<input class="input num" type="number" min="1" max="20" name="filas" value="${r?.filas || 4}">`)}${fld("Columnas", `<input class="input num" type="number" min="1" max="99" name="cols" value="${r?.cols || 10}">`)}${fld("Zona", `<select class="select" name="zona">${opts(["Picking A", "Reserva", "Volumen C", "Piso", "Recepción", "Despacho", "Cuarentena", "Virtual"], r?.zona || "Reserva")}</select>`)}${fld("Capacidad por ubicación", `<input class="input num" type="number" min="1" name="cap" value="${r?.cap || 6}">`)}</div><p class="small muted" id="rackHint"></p>`,
    `<button class="btn" data-close>Cancelar</button>${r && !STOCK.some(s => s.rack === r.id) ? `<button class="btn danger" data-a="rack-del" data-rack="${esc(r.id)}">${ic("trash")} Eliminar rack</button>` : ""}<button class="btn primary" data-a="rack-save" data-edit="${r ? 1 : 0}">${r ? "Guardar" : "Crear rack y ubicaciones"}</button>`,
    { onOpen: box => { const upd = () => { const v = formVals(box); const n = (v.filas || 0) * (v.cols || 0); const exist = r ? LOCATIONS.filter(l => l.rack === r.id).length : 0; $("#rackHint").innerHTML = r ? `Tiene ${exist} ubicaciones. Si amplías niveles o columnas se crean las nuevas (${Math.max(0, n - exist)}); reducir no elimina ubicaciones existentes.` : `Se generarán <b>${n} ubicaciones</b> con código <span class="mono">${esc(locCode(v.id || "?", 1, 1))} … ${esc(locCode(v.id || "?", v.cols || 1, v.filas || 1))}</span> y orden de recorrido en serpentina.`; }; upd(); box.addEventListener("input", upd); } });
}
ACTIONS["rack-new"] = () => rackModal();
ACTIONS["rack-edit"] = b => rackModal(R(b.dataset.rack));
ACTIONS["rack-save"] = b => run(b, async () => {
  const v = formVals($("#modalBox")); const id = (v.id || "").toUpperCase().replace(/\s+/g, "");
  if (!/^[A-Z0-9-]{1,12}$/.test(id)) throw new Error("Código inválido (letras, números y guion; máx. 12).");
  const edit = b.dataset.edit === "1"; if (!edit && RACKS.some(r => r.id === id)) throw new Error(`Ya existe el rack ${id}.`);
  if (!(v.filas >= 1 && v.filas <= 20 && v.cols >= 1 && v.cols <= 99)) throw new Error("Niveles 1–20 y columnas 1–99.");
  const r = edit ? R(id) : { id, wh: state.wh };
  Object.assign(r, { name: v.name || id, filas: v.filas, cols: v.cols, zona: v.zona, tipo: v.tipo, cap: v.cap || 6, wh: r.wh || state.wh });
  if (!edit) RACKS.push(r);
  await save("RACKS", r);
  const base = Math.max(0, ...LOCATIONS.map(l => l.sort || 0)) + 5; const nuevas = [];
  for (let c = 1; c <= v.cols; c++) for (let f = 1; f <= v.filas; f++) {
    const code = locCode(id, c, f); if (LOCATIONS.some(l => l.id === code)) continue;
    nuevas.push({ id: code, rack: id, fila: f, col: c, wh: r.wh, cap: v.cap || 6, sort: base + (c - 1) * v.filas + (c % 2 ? f : v.filas - f + 1), blocked: false, tipo: v.tipo });
  }
  await saveMany("LOCATIONS", nuevas); const created = nuevas.length;
  closeOverlays(); state.sub.ubicaciones = id; state.selLoc = null; go("ubicaciones");
  toast(edit ? `Rack ${esc(id)} actualizado${created ? ` · ${created} ubicaciones nuevas` : ""}.` : `Rack ${esc(id)} creado con ${created} ubicaciones. Imprime sus etiquetas con «Etiquetas del rack».`);
});
ACTIONS["rack-del"] = b => run(b, async () => { if (!await confirmDlg("Eliminar rack", `Se eliminará el rack <b>${esc(b.dataset.rack)}</b> y todas sus ubicaciones.`, { ok: "Eliminar", danger: true })) return; await del("RACKS", b.dataset.rack); RACKS.splice(RACKS.findIndex(r => r.id === b.dataset.rack), 1); closeOverlays(); state.sub.ubicaciones = null; render(); toast("Rack eliminado.", "info"); });
function locModal(l = null, rackId = null) {
  const r = R(l ? l.rack : rackId) || whRacks()[0]; if (!r) { toast("Primero crea un rack.", "bad"); return; }
  const nextCol = Math.max(0, ...LOCATIONS.filter(x => x.rack === r.id).map(x => x.col)) + 1;
  openModal(l ? `Editar ${esc(l.id)}` : "Nueva ubicación", `<div class="grid g-2">${fld("Rack / área", l ? `<input class="input mono" name="rack" value="${esc(l.rack)}" readonly>` : `<select class="select" name="rack">${whRacks().map(x => opt(x.id, r.id, `${x.id} · ${x.name}`)).join("")}</select>`)}${fld("Código", `<input class="input mono" name="id" value="${esc(l ? l.id : locCode(r.id, nextCol, 1))}" ${l ? "readonly" : ""}>`)}${fld("Columna", `<input class="input num" type="number" min="1" name="col" value="${l ? l.col : nextCol}" ${l ? "readonly" : ""}>`)}${fld("Nivel", `<input class="input num" type="number" min="1" name="fila" value="${l ? l.fila : 1}" ${l ? "readonly" : ""}>`)}${fld("Tipo", `<select class="select" name="tipo">${opts(["Picking", "Reserva", "Piso", "Cuarentena", "Muelle"], l?.tipo)}</select>`)}${fld("Capacidad", `<input class="input num" type="number" min="1" name="cap" value="${l?.cap || r.cap || 6}">`)}${fld("Orden de recorrido (sort_seq)", `<input class="input num" type="number" min="0" name="sort" value="${l ? l.sort : Math.max(0, ...LOCATIONS.map(x => x.sort || 0)) + 1}">`)}</div>`,
    `<button class="btn" data-close>Cancelar</button><button class="btn primary" data-a="loc-save" data-edit="${l ? 1 : 0}">${l ? "Guardar" : "Crear"}</button>`,
    { onOpen: box => { if (l) return; box.addEventListener("input", e => { if (["col", "fila", "rack"].includes(e.target.name)) { const v = formVals(box); $("[name=id]", box).value = locCode(v.rack, v.col || 1, v.fila || 1); } }); box.addEventListener("change", e => { if (e.target.name === "rack") { const v = formVals(box); $("[name=id]", box).value = locCode(v.rack, v.col || 1, v.fila || 1); } }); } });
}
ACTIONS["loc-new"] = b => locModal(null, b.dataset.rack);
ACTIONS["loc-edit"] = b => locModal(L(b.dataset.loc));
ACTIONS["loc-save"] = b => run(b, async () => {
  const v = formVals($("#modalBox")); const edit = b.dataset.edit === "1"; const id = (v.id || "").toUpperCase();
  if (!edit && LOCATIONS.some(l => l.id === id)) throw new Error(`La ubicación ${id} ya existe${setting("reutilizarUbic") ? "" : " (los códigos no se reutilizan)"}.`);
  if (!(v.col >= 1 && v.fila >= 1)) throw new Error("Columna y nivel deben ser mayores a cero.");
  const r = R(v.rack); const l = edit ? L(id) : { id, rack: r.id, fila: v.fila, col: v.col, wh: rackWh(r), blocked: false };
  Object.assign(l, { tipo: v.tipo, cap: v.cap || 6, sort: v.sort ?? l.sort ?? 0 }); if (!edit) LOCATIONS.push(l);
  await save("LOCATIONS", l);
  if (!edit && (v.col > r.cols || v.fila > r.filas)) { r.cols = Math.max(r.cols, v.col); r.filas = Math.max(r.filas, v.fila); await save("RACKS", r); }
  closeOverlays(); state.sub.ubicaciones = r.id; state.selLoc = id; render(); toast(`Ubicación ${esc(id)} ${edit ? "actualizada" : "creada"}.`);
});
